makeEx2(document.getElementById("ex-l18"),sim18,[{t:"Tự viết sắp xếp nhanh",d:"Đầu vào: n (1 ≤ n ≤ 10^5) rồi n số nguyên (|aᵢ| ≤ 10^9). Đầu ra: dãy xếp tăng dần. Tự cài sắp xếp nhanh trong hàm đệ quy qs, không dùng sort của thư viện. Bộ test hiệu quả dùng dãy đã xếp sẵn.",tests:[{in:"8\n7 2 9 4 5 8 1 6",out:"1 2 4 5 6 7 8 9"},{in:"1\n3",out:"3"},{in:"5\n4 4 4 4 4",out:"4 4 4 4 4"},{in:"6\n6 5 4 3 2 1",out:"1 2 3 4 5 6"},{in:"4\n-1000000000 1000000000 0 -5",out:"-1000000000 -5 0 1000000000"}],start:"#include <iostream>\nusing namespace std;\n\nint a[100000];\n\nvoid qs(int l, int r) {\n    // chọn chốt, phân hoạch, gọi đệ quy hai bên\n}\n\nint main() {\n    int n;\n    cin >> n;\n    for (int i = 0; i < n; i++) cin >> a[i];\n    qs(0, n - 1);\n    for (int i = 0; i < n; i++) cout << a[i] << (i + 1 < n ? \" \" : \"\\n\");\n    return 0;\n}",need:/^(?![\s\S]*\bsort\s*\()(?:[\s\S]*?\bqs\s*\(){4}/,needMsg:"Hãy tự cài sắp xếp nhanh bằng hàm đệ quy qs (gọi chính nó cho hai phần), không dùng sort của thư viện.",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>i).join(" "),ns:[250,500,1000,2000],need:"nlogn",limit:n=>60*n*Math.log2(n)+200,why:"Chốt kém (phần tử đầu hoặc cuối) làm sắp xếp nhanh thành O(n²) trên dãy đã xếp. Chọn chốt ở giữa."},py:{start:"n = int(input())\na = list(map(int, input().split()))\n\ndef qs(l, r):\n    # chọn chốt, phân hoạch, gọi đệ quy hai bên\n    pass\n\nqs(0, n - 1)\nprint(*a)",hints:["Chọn chốt ở giữa đoạn; chốt ở đầu sẽ thành O(n²) trên dãy đã xếp sẵn (và đệ quy quá sâu).","Dùng a[i] < p và a[j] > p (không dùng <=, >=) để i, j dừng lại ở các số bằng chốt."],needMsg:"Hãy tự cài sắp xếp nhanh bằng hàm đệ quy qs (gọi chính nó cho hai phần), không dùng sort hay sorted.",need:/^(?![\s\S]*\bsort(ed)?\s*\()(?:[\s\S]*?\bqs\s*\(){4}/},cs:{start:"using System;\n\nclass Program\n{\n    static int[] a;\n\n    static void QuickSort(int l, int r)\n    {\n        // chọn chốt, phân hoạch, gọi đệ quy hai bên\n    }\n\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        QuickSort(0, n - 1);\n        Console.WriteLine(string.Join(\" \", a));\n    }\n}",hints:["Chọn chốt ở giữa đoạn; chốt ở đầu sẽ thành O(n²) trên dãy đã xếp sẵn.","Dùng a[i] < p và a[j] > p (không dùng <=, >=) để i, j dừng lại ở các số bằng chốt: dãy toàn số bằng nhau vẫn chia đều.","Đổi chỗ bằng (a[i], a[j]) = (a[j], a[i]);"],needMsg:"Hãy tự cài sắp xếp nhanh trong hàm đệ quy QuickSort (gọi chính nó cho hai phần), không dùng Array.Sort, List.Sort hay OrderBy.",need:/^(?![\s\S]*\b(Sort|OrderBy|OrderByDescending)\s*\()(?:[\s\S]*?\bQuickSort\s*\(){4}/}},{t:"Số nhỏ thứ k",d:"Đầu vào: n và k (1 ≤ k ≤ n ≤ 10^5), rồi n số nguyên (|aᵢ| ≤ 10^9). Đầu ra: số đứng ở vị trí thứ k (tính từ 1) nếu xếp dãy tăng dần.",tests:[{in:"8 6\n7 2 9 4 5 8 1 6",out:"7"},{in:"1 1\n5",out:"5"},{in:"5 3\n2 2 2 1 1",out:"2"},{in:"4 1\n9 -3 7 0",out:"-3"},{in:"4 4\n9 -3 7 0",out:"9"}],start:"#include <iostream>\nusing namespace std;\n\nint a[100000];\n\nint main() {\n    int n, k;\n    cin >> n >> k;\n    for (int i = 0; i < n; i++) cin >> a[i];\n    // quickselect: phân hoạch, rồi chỉ đi tiếp vào một bên\n    return 0;\n}",perf:{gen:n=>n+" "+(n>>1)+"\n"+Array.from({length:n},(_,i)=>(i*7919)%1000003).join(" "),ns:[500,2000,8000],need:"n",limit:n=>70*n+400,why:"Sắp xếp cả dãy tốn O(n log n). Quickselect chỉ đi vào một bên nên trung bình O(n)."},py:{start:"n, k = map(int, input().split())\na = list(map(int, input().split()))\n# quickselect: phân hoạch, rồi chỉ đi tiếp vào một bên",hints:["Đổi k sang chỉ số từ 0. Sau mỗi lần phân hoạch, chỉ giữ lại phần chứa vị trí k.","Viết bằng vòng lặp (cập nhật l hoặc r) thay cho đệ quy."]},cs:{start:"using System;\n\nclass Program\n{\n    static int[] a;\n\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]), k = int.Parse(t[1]);\n        a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        // quickselect: phân hoạch, rồi chỉ đi tiếp vào một bên\n    }\n}",hints:["Đổi k sang chỉ số từ 0. Sau mỗi lần phân hoạch, chỉ giữ lại phần chứa vị trí k.","Có thể viết bằng vòng lặp thay cho đệ quy: cập nhật l hoặc r."]}},{t:"Ba màu",d:"Đầu vào: n (1 ≤ n ≤ 10^5) rồi n số, mỗi số là 0, 1 hoặc 2. Đầu ra: dãy sau khi xếp tăng dần. Yêu cầu: một lần duyệt, đổi chỗ trực tiếp trên mảng (không đếm rồi in lại, không dùng sort).",tests:[{in:"6\n2 0 2 1 1 0",out:"0 0 1 1 2 2"},{in:"1\n1",out:"1"},{in:"3\n2 2 2",out:"2 2 2"},{in:"5\n1 0 2 0 1",out:"0 0 1 1 2"}],start:"#include <iostream>\nusing namespace std;\n\nint a[100000];\n\nint main() {\n    int n;\n    cin >> n;\n    for (int i = 0; i < n; i++) cin >> a[i];\n    // lo: biên vùng 0, i: đang xét, hi: biên vùng 2\n    for (int i = 0; i < n; i++) cout << a[i] << (i + 1 < n ? \" \" : \"\\n\");\n    return 0;\n}",need:/^(?![\s\S]*\bsort\s*\()(?![\s\S]*\bcnt\w*\s*\[)/,needMsg:"Hãy đổi chỗ trực tiếp bằng ba con trỏ (lo, i, hi); không dùng sort hay mảng đếm.",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>(i*7)%3).join(" "),ns:[500,2000,8000],need:"n",limit:n=>60*n+200,why:"Một lần duyệt với ba con trỏ là đủ, O(n)."},py:{start:"n = int(input())\na = list(map(int, input().split()))\n# lo: biên vùng 0, i: đang xét, hi: biên vùng 2\nprint(*a)",hints:["Phân hoạch ba phần (bài toán lá cờ Hà Lan): a[0..lo−1] là 0, a[lo..i−1] là 1, a[hi+1..n−1] là 2, a[i..hi] chưa xét.","Gặp 2 thì đổi với a[hi] và giảm hi, nhưng KHÔNG tăng i: số vừa đổi về chưa được xét."],needMsg:"Hãy đổi chỗ trực tiếp bằng ba con trỏ (lo, i, hi); không dùng sort, sorted, count hay danh sách đếm.",need:/^(?![\s\S]*\bsort(ed)?\s*\()(?![\s\S]*\bcount\s*\()(?![\s\S]*\bcnt\w*\s*\[)/},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        // lo: biên vùng 0, i: đang xét, hi: biên vùng 2\n        Console.WriteLine(string.Join(\" \", a));\n    }\n}",hints:["Phân hoạch ba phần (bài toán lá cờ Hà Lan): a[0..lo−1] là 0, a[lo..i−1] là 1, a[hi+1..n−1] là 2, a[i..hi] chưa xét.","Gặp 2 thì đổi với a[hi] và giảm hi, nhưng KHÔNG tăng i: số vừa đổi về chưa được xét."],needMsg:"Hãy đổi chỗ trực tiếp trên mảng trong một lần duyệt (phân hoạch ba phần), không đếm rồi in lại, không dùng Sort.",need:/^(?![\s\S]*\b(Sort|OrderBy|OrderByDescending)\s*\()(?![\s\S]*\bcnt\w*\s*\[)/}}]);

makeQuiz("quiz18","score18",[{"q": "Sau một lần phân hoạch Hoare quanh chốt p (i vượt qua j), điều gì đúng?", "o": ["Dãy đã sắp xếp", "a[l..j] ≤ p và a[i..r] ≥ p", "p ở đúng vị trí giữa", "a[l..j] < p và a[i..r] > p"], "a": 1, "e": "Hai đoạn chưa được sắp xếp bên trong, chỉ được tách theo chốt; số bằng p có thể ở cả hai bên."}, {"q": "Sắp xếp nhanh chọn chốt là phần tử đầu, chạy trên dãy đã tăng sẵn. Độ phức tạp?", "o": ["O(n)", "O(n log n)", "O(n²)", "O(log n)"], "a": 2, "e": "Mỗi lần chỉ tách được một phần tử, đệ quy sâu n tầng."}, {"q": "Vì sao quickselect trung bình chỉ O(n)?", "o": ["Vì không phân hoạch", "Vì chỉ đi tiếp vào một bên, tổng n + n/2 + n/4 + … ≈ 2n", "Vì dùng mảng phụ", "Vì k nhỏ"], "a": 1, "e": "Khác sắp xếp nhanh phải xử lý cả hai bên ở mỗi tầng."}, {"q": "Khi đi thi, cần sắp xếp 10⁶ số nguyên, nên làm gì?", "o": ["Tự viết sắp xếp nhanh chốt đầu", "Dùng sort của STL", "Dùng sắp xếp nổi bọt", "Dùng sắp xếp chọn"], "a": 1, "e": "sort của STL là introsort, luôn O(n log n) và đã được tối ưu kỹ.", "lang": ["cpp"]}, {"q": "Khi đi thi bằng Python, cần sắp xếp 10⁶ số nguyên, nên làm gì?", "o": ["Tự viết sắp xếp nhanh chốt đầu", "Dùng a.sort() hoặc sorted(a)", "Dùng sắp xếp nổi bọt", "Dùng sắp xếp chọn"], "a": 1, "e": "Timsort của Python luôn O(n log n) và chạy bằng C, nhanh hơn nhiều so với vòng lặp Python tự viết.", "lang": ["py"]}, {"q": "Khi đi thi bằng C#, cần sắp xếp 10⁶ số nguyên, nên làm gì?", "o": ["Tự viết sắp xếp nhanh chốt đầu", "Dùng Array.Sort(a)", "Dùng sắp xếp nổi bọt", "Dùng sắp xếp chọn"], "a": 1, "e": "Array.Sort dùng introsort, luôn O(n log n) và đã được tối ưu kỹ.", "lang": ["cs"]}]);

